const startTime = Date.now();
$execution.customData.set('start_time', String(startTime));
$execution.customData.set('total_mentions', '0');
$execution.customData.set('total_alerts', '0');
$execution.customData.set('errors', '[]');
console.log('[NEXO News] Iniciando coleta - ' + new Date().toISOString());
return [{ json: { start_time: startTime, timestamp: new Date().toISOString() } }];

const entities = $input.all();
if (!entities || entities.length === 0) {
  console.log('[NEXO News] Nenhuma entidade monitorada ativa encontrada.');
  return [];
}
console.log('[NEXO News] Entidades encontradas: ' + entities.length);
return entities.map(e => ({ json: e.json }));

const entity = $input.first().json;
const entityName = entity.name || '';
const entityType = entity.entity_type || 'candidate';

let searchQuery = `\"${entityName}\" notícias`;
if (entityType === 'candidate') searchQuery = `\"${entityName}\" candidato político notícias`;
else if (entityType === 'opponent') searchQuery = `\"${entityName}\" adversário político`;
else if (entityType === 'party') searchQuery = `\"${entityName}\" partido político`;
else if (entityType === 'influencer') searchQuery = `\"${entityName}\" influenciador`;
else if (entityType === 'portal') searchQuery = `site:${entityName}`;

const encodedQuery = encodeURIComponent(searchQuery);
console.log('[NEXO News] Pesquisando entidade: ' + entityName + ' | Query: ' + searchQuery);

return [{ json: { ...entity, search_query: searchQuery, encoded_query: encodedQuery } }];

const entity = $('Construir Query de Pesquisa').first()?.json || {};
const serpItems = $('Pesquisar Notícias (SerpAPI)').all();
let newsApiItems = [];
try { newsApiItems = $('Pesquisar Notícias (NewsAPI)').all(); } catch (e) { newsApiItems = []; }

let articles = [];

// Processar SerpAPI
try {
  const serpData = serpItems[0]?.json || {};
  if (serpData.news_results && Array.isArray(serpData.news_results)) {
    const serpArticles = serpData.news_results.map(a => ({
      title: a.title || '',
      url: a.link || '',
      source_name: a.source?.name || a.source || '',
      published_at: a.date || new Date().toISOString(),
      snippet: a.snippet || '',
      author: a.author || '',
      api_source: 'serpapi'
    }));
    articles = [...articles, ...serpArticles];
  }
} catch(e) { console.log('[NEXO] Erro SerpAPI: ' + e.message); }

// Processar NewsAPI
try {
  const newsData = newsApiItems[0]?.json || {};
  if (newsData.articles && Array.isArray(newsData.articles)) {
    const newsArticles = newsData.articles
      .filter(a => a.title && a.title !== '[Removed]')
      .map(a => ({
        title: a.title || '',
        url: a.url || '',
        source_name: a.source?.name || '',
        published_at: a.publishedAt || new Date().toISOString(),
        snippet: a.description || '',
        content: a.content || '',
        author: a.author || '',
        api_source: 'newsapi'
      }));
    articles = [...articles, ...newsArticles];
  }
} catch(e) { console.log('[NEXO] Erro NewsAPI: ' + e.message); }

// Deduplica por URL
const seen = new Set();
const unique = articles.filter(a => {
  if (!a.url || seen.has(a.url)) return false;
  seen.add(a.url);
  return true;
});

// Converte datas do SerpAPI (relativas: 'ha 2 dias', '2 weeks ago'; absolutas: '16/07/2026', '16 de jul. de 2026') em ISO real.
function parseNewsDate(raw) {
  if (!raw) return null;
  const s = String(raw).trim();
  const low = s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const now = Date.now();
  const UNIT_MS = { minuto: 60000, min: 60000, minute: 60000, hora: 3600000, hour: 3600000, dia: 86400000, day: 86400000, semana: 604800000, week: 604800000, mes: 2592000000, month: 2592000000, ano: 31536000000, year: 31536000000 };
  const rel = low.match(/(\d+)\s*(minutos?|mins?|minutes?|horas?|hours?|dias?|days?|semanas?|weeks?|mes(?:es)?|months?|anos?|years?)/);
  if (rel && /(\bha\b|atras|\bago\b)/.test(low)) {
    const unit = rel[2];
    const ms = UNIT_MS[unit] || UNIT_MS[unit.replace(/es$/, '')] || UNIT_MS[unit.replace(/s$/, '')];
    if (ms) return new Date(now - parseInt(rel[1], 10) * ms).toISOString();
  }
  if (/ontem|yesterday/.test(low)) return new Date(now - 86400000).toISOString();
  if (/\bhoje\b|\btoday\b|\bagora\b|\bnow\b/.test(low)) return new Date(now).toISOString();
  const br = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (br) return new Date(Date.UTC(+br[3], +br[2] - 1, +br[1], 12)).toISOString();
  const meses = ['jan','fev','mar','abr','mai','jun','jul','ago','set','out','nov','dez'];
  const ptm = low.match(/(\d{1,2})\s*(?:de\s*)?(jan|fev|mar|abr|mai|jun|jul|ago|set|out|nov|dez)\w*\.?\s*(?:de\s*)?(\d{4})/);
  if (ptm) return new Date(Date.UTC(+ptm[3], meses.indexOf(ptm[2]), +ptm[1], 12)).toISOString();
  const d = new Date(s);
  if (!isNaN(d.getTime())) return d.toISOString();
  return null;
}

// Descarta artigos com mais de 7 dias (defesa extra alem do tbs=qdr:w da busca).
const cutoff = Date.now() - 7 * 86400000;
const fresh = unique
  .map(a => ({ ...a, published_at_parsed: parseNewsDate(a.published_at) }))
  .filter(a => a.published_at_parsed === null || new Date(a.published_at_parsed).getTime() >= cutoff);

console.log('[NEXO News] Entidade: ' + entity.name + ' | Artigos: ' + unique.length + ' | Recentes (<=7d): ' + fresh.length);

if (fresh.length === 0) {
  return [{ json: { ...entity, no_articles: true } }];
}

return fresh.map(a => ({ json: { ...entity, article: a } }));

// Roda 1x por item: $('Nó').item resolve o item pareado corretamente.
const item = $('Mesclar Fontes de Notícias').item.json;

// Extrair HTML da resposta do HTTP Request
const httpResponse = $input.item.json;
const rawHtml = httpResponse?.data || httpResponse?.body || httpResponse?.html || (typeof httpResponse === 'string' ? httpResponse : '') || '';

let cleanContent = '';
if (rawHtml && typeof rawHtml === 'string') {
  cleanContent = rawHtml
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/\s+/g, ' ')
    .trim()
    .substring(0, 3000);
}

const finalContent = cleanContent || item.article?.snippet || item.article?.content || '';

console.log('[NEXO News] campaign_id=' + item.campaign_id + ' | entity_id=' + item.id + ' | url=' + item.article?.url);

return { json: { ...item, article: { ...item.article, full_content: finalContent } } };

// Casa artigo x resposta da IA POR POSICAO: o Basic LLM Chain nao propaga
// paired item, entao a referencia .item quebra. $input.all() preserva a ordem 1:1.
const artigos = $('Extrair Conteúdo Limpo (FIXED)').all();
const respostas = $input.all();

return artigos.map((art, i) => {
  const item = art.json;
  const aiResponse = respostas[i]?.json || {};

  let analysis = {
    sentiment: 'neutral',
    relevance_score: 0.5,
    impact_score: 0.5,
    summary: item.article?.snippet || '',
    principais_temas: [],
    citacao_direta: false,
    mencao_adversario: false,
    criticidade: 'low',
    justificativa: ''
  };

  try {
    // Basic LLM Chain devolve o texto em .text (ou .output em versoes mais novas).
    const raw = aiResponse?.text ?? aiResponse?.output ?? '{}';
    if (raw && typeof raw === 'object') {
      analysis = { ...analysis, ...raw };
    } else {
      const cleaned = String(raw).replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
      analysis = { ...analysis, ...JSON.parse(cleaned) };
    }
  } catch(e) {
    console.log('[NEXO] Erro ao parsear IA: ' + e.message);
  }

  // Usa a data ja parseada no no de mesclagem; so cai em 'agora' em ultimo caso.
  let parsedDate = item.article?.published_at_parsed || null;
  if (!parsedDate) {
    const d = new Date(item.article?.published_at || '');
    parsedDate = isNaN(d.getTime()) ? new Date().toISOString() : d.toISOString();
  }

  const mention = {
    campaign_id: item.campaign_id,
    entity_id: item.id,
    source: 'news',
    title: (item.article?.title || '').substring(0, 500),
    content: item.article?.full_content || item.article?.snippet || '',
    sentiment: analysis.sentiment,
    url: item.article?.url || '',
    published_at: parsedDate,
    created_at: new Date().toISOString(),
    metadata: {
      source_name: item.article?.source_name || '',
      author: item.article?.author || '',
      relevance_score: analysis.relevance_score,
      impact_score: analysis.impact_score,
      summary: analysis.summary,
      principais_temas: analysis.principais_temas,
      citacao_direta: analysis.citacao_direta,
      mencao_adversario: analysis.mencao_adversario,
      criticidade: analysis.criticidade,
      justificativa: analysis.justificativa,
      api_source: item.article?.api_source || 'unknown',
      entity_type: item.entity_type,
      entity_name: item.name
    }
  };

  return { json: { mention, analysis, entity: item } };
});

const mentions = $('Construir Mention').all();
const alerts = [];
const now = new Date().toISOString();

for (const _m of mentions) {
const item = _m.json;
const analysis = item.analysis || {};
const entity = item.entity || {};
const mention = item.mention || {};
const mentionAlerts = [];

// Regra 1: Sentimento negativo crítico
if (analysis.sentiment === 'negative' && analysis.impact_score >= 0.7) {
  mentionAlerts.push({
    campaign_id: entity.campaign_id,
    entity_id: entity.id,
    type: 'negative_sentiment',
    title: `Cobertura Negativa: ${entity.name}`,
    description: `Notícia com sentimento negativo de alto impacto detectada: "${mention.title}"`,
    severity: analysis.impact_score >= 0.9 ? 'critical' : 'high',
    source_url: mention.url,
    metadata: JSON.stringify({ relevance_score: analysis.relevance_score, impact_score: analysis.impact_score, source: mention.metadata?.source_name }),
    created_at: now,
    read: false
  });
}

// Regra 2: Matéria altamente relevante
if (analysis.relevance_score >= 0.85) {
  mentionAlerts.push({
    campaign_id: entity.campaign_id,
    entity_id: entity.id,
    type: 'high_relevance',
    title: `Alta Relevância: ${entity.name}`,
    description: `Matéria de alta relevância detectada: "${mention.title}"`,
    severity: 'high',
    source_url: mention.url,
    metadata: JSON.stringify({ relevance_score: analysis.relevance_score, temas: analysis.principais_temas }),
    created_at: now,
    read: false
  });
}

// Regra 3: Citação direta do candidato
if (analysis.citacao_direta && entity.entity_type === 'candidate') {
  mentionAlerts.push({
    campaign_id: entity.campaign_id,
    entity_id: entity.id,
    type: 'direct_quote',
    title: `Citação Direta: ${entity.name}`,
    description: `${entity.name} foi citado diretamente em: "${mention.title}"`,
    severity: analysis.sentiment === 'negative' ? 'high' : 'medium',
    source_url: mention.url,
    metadata: JSON.stringify({ sentiment: analysis.sentiment, source: mention.metadata?.source_name }),
    created_at: now,
    read: false
  });
}

// Regra 4: Citação direta do adversário
if (analysis.citacao_direta && entity.entity_type === 'opponent') {
  mentionAlerts.push({
    campaign_id: entity.campaign_id,
    entity_id: entity.id,
    type: 'opponent_mention',
    title: `Adversário Citado: ${entity.name}`,
    description: `Adversário ${entity.name} foi citado diretamente em: "${mention.title}"`,
    severity: 'medium',
    source_url: mention.url,
    metadata: JSON.stringify({ sentiment: analysis.sentiment, impact_score: analysis.impact_score }),
    created_at: now,
    read: false
  });
}

// Regra 5: Criticidade crítica pela IA
if (analysis.criticidade === 'critical') {
  const exists = mentionAlerts.find(a => a.type === 'negative_sentiment');
  if (!exists) {
    mentionAlerts.push({
      campaign_id: entity.campaign_id,
      entity_id: entity.id,
      type: 'critical_coverage',
      title: `Cobertura Crítica: ${entity.name}`,
      description: `IA classificou como CRÍTICO: "${mention.title}" - ${analysis.justificativa}`,
      severity: 'critical',
      source_url: mention.url,
      metadata: JSON.stringify({ justificativa: analysis.justificativa, temas: analysis.principais_temas }),
      created_at: now,
      read: false
    });
  }
}

console.log('[NEXO News] Alertas gerados para ' + entity.name + ': ' + mentionAlerts.length);
alerts.push(...mentionAlerts);
}
return alerts.map(a => ({ json: a }));

// Contabilizar para log final
const saved = $input.all();
console.log('[NEXO News] ' + saved.length + ' alertas salvos.');
return saved;

// Log quando não há artigos para a entidade
const entity = $input.first().json;
console.log('[NEXO News] Sem artigos para: ' + entity.name);
return [{ json: { entity_name: entity.name, status: 'no_articles' } }];

const endTime = Date.now();
const startTime = Number($execution.customData.get('start_time')) || endTime;
const durationMs = endTime - startTime;
const durationSec = (durationMs / 1000).toFixed(2);

console.log('=== NEXO News Collector - Relatório Final ===');
console.log('Tempo de execução: ' + durationSec + 's');
console.log('Execução concluída em: ' + new Date().toISOString());

return [{
  json: {
    status: 'completed',
    execution_time_sec: parseFloat(durationSec),
    completed_at: new Date().toISOString()
  }
}];

const error = $input.first().json;
console.error('[NEXO News] ERRO CRÍTICO:', JSON.stringify(error, null, 2));

const errorLog = {
  workflow: 'NEXO - News Collector',
  error_message: error.error?.message || error.message || 'Erro desconhecido',
  error_node: error.error?.node?.name || 'unknown',
  error_stack: error.error?.stack || '',
  occurred_at: new Date().toISOString()
};

console.log('[NEXO News] Log de erro registrado:', JSON.stringify(errorLog));
return [{ json: errorLog }];
